/**
 * JSON validation utility script.
 * Reads JSON from stdin and validates it.
 */

/**
 * Read all data from stdin.
 */
async function readStdin(): Promise<string> {
  const chunks: string[] = [];
  for await (const chunk of Bun.stdin.stream()) {
    chunks.push(Buffer.from(chunk).toString());
  }
  return chunks.join("");
}

/**
 * Validate JSON string.
 */
export function validateJson(input: string): { valid: boolean; error?: string } {
  if (!input || input.trim() === "") {
    return { valid: false, error: "Empty input" };
  }

  try {
    JSON.parse(input);
    return { valid: true };
  } catch (error) {
    const message = error instanceof Error ? error.message : "Unknown error";
    return { valid: false, error: message };
  }
}

/**
 * Main execution function.
 */
async function main(): Promise<void> {
  try {
    const input = await readStdin();
    const result = validateJson(input);

    if (result.valid) {
      console.log("✓ Valid JSON");
      process.exit(0);
    } else {
      console.error(`✗ Invalid JSON: ${result.error}`);
      process.exit(1);
    }
  } catch (error) {
    const message = error instanceof Error ? error.message : "Unknown error";
    console.error(`Error: ${message}`);
    process.exit(1);
  }
}

if (import.meta.main) {
  main();
}

import { describe, expect, test } from "bun:test";
import { validateJson } from "./validate-json";

describe("validateJson", () => {
  test("validates correct JSON object", () => {
    const result = validateJson('{"name": "Alice", "age": 30}');
    expect(result.valid).toBe(true);
    expect(result.error).toBeUndefined();
  });

  test("validates correct JSON array", () => {
    const result = validateJson('[1, 2, 3]');
    expect(result.valid).toBe(true);
    expect(result.error).toBeUndefined();
  });

  test("validates JSON primitives", () => {
    expect(validateJson('"string"').valid).toBe(true);
    expect(validateJson('123').valid).toBe(true);
    expect(validateJson('true').valid).toBe(true);
    expect(validateJson('null').valid).toBe(true);
  });

  test("rejects malformed JSON with missing quote", () => {
    const result = validateJson('{"name": "Alice}');
    expect(result.valid).toBe(false);
    expect(result.error).toBeDefined();
  });

  test("rejects malformed JSON with trailing comma", () => {
    const result = validateJson('{"name": "Alice",}');
    expect(result.valid).toBe(false);
    expect(result.error).toBeDefined();
  });

  test("rejects malformed JSON with invalid syntax", () => {
    const result = validateJson('{name: "Alice"}');
    expect(result.valid).toBe(false);
    expect(result.error).toBeDefined();
  });

  test("rejects empty input", () => {
    const result = validateJson("");
    expect(result.valid).toBe(false);
    expect(result.error).toBe("Empty input");
  });

  test("rejects whitespace-only input", () => {
    const result = validateJson("   \n  ");
    expect(result.valid).toBe(false);
    expect(result.error).toBe("Empty input");
  });
});

