/**
 * High-performance JSON validation utility.
 */

export interface ValidationResult {
  valid: boolean;
  data?: unknown;
  error?: ValidationError;
}

export interface ValidationError {
  message: string;
  line?: number;
  column?: number;
}

export interface Schema {
  type: "object" | "array" | "string" | "number" | "boolean" | "null";
  properties?: Record<string, Schema>;
  items?: Schema;
  required?: string[];
}

/**
 * Validates a JSON string using Bun's native parser.
 * Fast-path validation for syntax checking.
 */
export function validateJson(input: string): ValidationResult {
  try {
    const data = JSON.parse(input);
    return { valid: true, data };
  } catch (err) {
    const error = extractParseError(err, input);
    return { valid: false, error };
  }
}

/**
 * Validates JSON string against a schema.
 */
export function validateJsonWithSchema(
  input: string,
  schema: Schema
): ValidationResult {
  const parseResult = validateJson(input);
  if (!parseResult.valid) {
    return parseResult;
  }

  const schemaError = validateAgainstSchema(parseResult.data, schema);
  if (schemaError) {
    return { valid: false, error: schemaError };
  }

  return { valid: true, data: parseResult.data };
}

/**
 * Extracts error details from JSON parse exception.
 */
function extractParseError(err: unknown, input: string): ValidationError {
  const message = err instanceof Error ? err.message : String(err);

  const positionMatch = message.match(/position (\d+)/);
  if (positionMatch) {
    const position = parseInt(positionMatch[1], 10);
    const { line, column } = getLineColumn(input, position);
    return { message, line, column };
  }

  const lineMatch = message.match(/line (\d+)/);
  const columnMatch = message.match(/column (\d+)/);

  if (lineMatch || columnMatch) {
    return {
      message,
      line: lineMatch ? parseInt(lineMatch[1], 10) : undefined,
      column: columnMatch ? parseInt(columnMatch[1], 10) : undefined,
    };
  }

  return { message };
}

/**
 * Converts character position to line and column numbers.
 */
function getLineColumn(input: string, position: number): { line: number; column: number } {
  let line = 1;
  let column = 1;

  for (let i = 0; i < position && i < input.length; i++) {
    if (input[i] === "\n") {
      line++;
      column = 1;
    } else {
      column++;
    }
  }

  return { line, column };
}

/**
 * Validates data against a schema using type guards.
 */
function validateAgainstSchema(data: unknown, schema: Schema): ValidationError | null {
  const actualType = getType(data);

  if (actualType !== schema.type) {
    return {
      message: `Expected type "${schema.type}", got "${actualType}"`,
    };
  }

  if (schema.type === "object" && typeof data === "object" && data !== null) {
    if (schema.required) {
      for (const key of schema.required) {
        if (!(key in data)) {
          return {
            message: `Missing required property "${key}"`,
          };
        }
      }
    }

    if (schema.properties) {
      for (const [key, propSchema] of Object.entries(schema.properties)) {
        if (key in data) {
          const propData = (data as Record<string, unknown>)[key];
          const error = validateAgainstSchema(propData, propSchema);
          if (error) {
            return {
              message: `Property "${key}": ${error.message}`,
            };
          }
        }
      }
    }
  }

  if (schema.type === "array" && Array.isArray(data)) {
    if (schema.items) {
      for (let i = 0; i < data.length; i++) {
        const error = validateAgainstSchema(data[i], schema.items);
        if (error) {
          return {
            message: `Array item ${i}: ${error.message}`,
          };
        }
      }
    }
  }

  return null;
}

/**
 * Gets the schema type of a value.
 */
function getType(value: unknown): Schema["type"] {
  if (value === null) return "null";
  if (Array.isArray(value)) return "array";
  return typeof value as Schema["type"];
}

import { describe, expect, test } from "bun:test";
import {
  validateJson,
  validateJsonWithSchema,
  type Schema,
} from "./json-validator";

describe("json-validator", () => {
  describe("validateJson", () => {
    test("validates simple valid JSON", () => {
      const result = validateJson('{"name": "Alice"}');
      expect(result.valid).toBe(true);
      expect(result.data).toEqual({ name: "Alice" });
      expect(result.error).toBeUndefined();
    });

    test("validates arrays", () => {
      const result = validateJson('[1, 2, 3]');
      expect(result.valid).toBe(true);
      expect(result.data).toEqual([1, 2, 3]);
    });

    test("validates nested structures", () => {
      const result = validateJson('{"users": [{"id": 1}, {"id": 2}]}');
      expect(result.valid).toBe(true);
      expect(result.data).toEqual({ users: [{ id: 1 }, { id: 2 }] });
    });

    test("validates primitives", () => {
      expect(validateJson('"hello"').valid).toBe(true);
      expect(validateJson('42').valid).toBe(true);
      expect(validateJson('true').valid).toBe(true);
      expect(validateJson('null').valid).toBe(true);
    });

    test("rejects invalid JSON syntax", () => {
      const result = validateJson('{"name": "Alice"');
      expect(result.valid).toBe(false);
      expect(result.error).toBeDefined();
      expect(result.error?.message).toBeTruthy();
    });

    test("rejects trailing comma", () => {
      const result = validateJson('{"name": "Alice",}');
      expect(result.valid).toBe(false);
    });

    test("rejects malformed input", () => {
      const result = validateJson('not json at all');
      expect(result.valid).toBe(false);
      expect(result.error?.message).toBeTruthy();
    });

    test("provides error location for syntax errors", () => {
      const result = validateJson('{"name": invalid}');
      expect(result.valid).toBe(false);
      expect(result.error).toBeDefined();
    });

    test("handles empty input", () => {
      const result = validateJson('');
      expect(result.valid).toBe(false);
    });
  });

  describe("validateJsonWithSchema", () => {
    test("validates object against schema", () => {
      const schema: Schema = {
        type: "object",
        properties: {
          name: { type: "string" },
          age: { type: "number" },
        },
        required: ["name"],
      };

      const result = validateJsonWithSchema(
        '{"name": "Alice", "age": 30}',
        schema
      );
      expect(result.valid).toBe(true);
      expect(result.data).toEqual({ name: "Alice", age: 30 });
    });

    test("rejects missing required property", () => {
      const schema: Schema = {
        type: "object",
        properties: {
          name: { type: "string" },
        },
        required: ["name"],
      };

      const result = validateJsonWithSchema('{"age": 30}', schema);
      expect(result.valid).toBe(false);
      expect(result.error?.message).toContain("required");
    });

    test("rejects wrong type", () => {
      const schema: Schema = {
        type: "object",
        properties: {
          age: { type: "number" },
        },
      };

      const result = validateJsonWithSchema('{"age": "thirty"}', schema);
      expect(result.valid).toBe(false);
      expect(result.error?.message).toContain("number");
    });

    test("validates array with items schema", () => {
      const schema: Schema = {
        type: "array",
        items: { type: "number" },
      };

      const result = validateJsonWithSchema('[1, 2, 3]', schema);
      expect(result.valid).toBe(true);
    });

    test("rejects array with wrong item types", () => {
      const schema: Schema = {
        type: "array",
        items: { type: "number" },
      };

      const result = validateJsonWithSchema('[1, "two", 3]', schema);
      expect(result.valid).toBe(false);
      expect(result.error?.message).toContain("Array item");
    });

    test("validates nested objects", () => {
      const schema: Schema = {
        type: "object",
        properties: {
          user: {
            type: "object",
            properties: {
              name: { type: "string" },
            },
            required: ["name"],
          },
        },
      };

      const result = validateJsonWithSchema(
        '{"user": {"name": "Alice"}}',
        schema
      );
      expect(result.valid).toBe(true);
    });

    test("validates all primitive types", () => {
      expect(
        validateJsonWithSchema('"text"', { type: "string" }).valid
      ).toBe(true);
      expect(validateJsonWithSchema('42', { type: "number" }).valid).toBe(
        true
      );
      expect(
        validateJsonWithSchema('true', { type: "boolean" }).valid
      ).toBe(true);
      expect(validateJsonWithSchema('null', { type: "null" }).valid).toBe(
        true
      );
    });

    test("returns parse error for invalid JSON", () => {
      const schema: Schema = { type: "object" };
      const result = validateJsonWithSchema('invalid', schema);
      expect(result.valid).toBe(false);
      expect(result.error?.message).toBeTruthy();
    });
  });

  describe("performance", () => {
    test("validates large JSON quickly", () => {
      const largeObject = {
        users: Array.from({ length: 1000 }, (_, i) => ({
          id: i,
          name: `User ${i}`,
          email: `user${i}@example.com`,
          active: i % 2 === 0,
        })),
      };
      const json = JSON.stringify(largeObject);

      const start = performance.now();
      const result = validateJson(json);
      const duration = performance.now() - start;

      expect(result.valid).toBe(true);
      expect(duration).toBeLessThan(10);
    });

    test("validates with schema quickly", () => {
      const schema: Schema = {
        type: "object",
        properties: {
          users: {
            type: "array",
            items: {
              type: "object",
              properties: {
                id: { type: "number" },
                name: { type: "string" },
              },
            },
          },
        },
      };

      const data = {
        users: Array.from({ length: 100 }, (_, i) => ({
          id: i,
          name: `User ${i}`,
        })),
      };
      const json = JSON.stringify(data);

      const start = performance.now();
      const result = validateJsonWithSchema(json, schema);
      const duration = performance.now() - start;

      expect(result.valid).toBe(true);
      expect(duration).toBeLessThan(50);
    });

    test("handles deeply nested structures", () => {
      let nested: Record<string, unknown> = { value: 42 };
      for (let i = 0; i < 50; i++) {
        nested = { nested };
      }
      const json = JSON.stringify(nested);

      const result = validateJson(json);
      expect(result.valid).toBe(true);
    });
  });
});

