/**
 * Main entry point for the rp1 eval test project.
 */

import { greet } from "./utils";
import { validateJson, validateJsonWithSchema, type Schema } from "./json-validator";

const args = process.argv.slice(2);
const command = args[0];

if (command === "validate") {
  const input = args[1];
  if (!input) {
    console.error("Usage: bun run src/index.ts validate <json-string>");
    process.exit(1);
  }

  const result = validateJson(input);
  if (result.valid) {
    console.log("Valid JSON");
    console.log(JSON.stringify(result.data, null, 2));
  } else {
    console.error("Invalid JSON:");
    console.error(`  ${result.error?.message}`);
    if (result.error?.line !== undefined) {
      console.error(`  Line: ${result.error.line}, Column: ${result.error.column}`);
    }
    process.exit(1);
  }
} else if (command === "validate-schema") {
  const input = args[1];
  const schemaJson = args[2];

  if (!input || !schemaJson) {
    console.error("Usage: bun run src/index.ts validate-schema <json-string> <schema-json>");
    process.exit(1);
  }

  let schema: Schema;
  try {
    schema = JSON.parse(schemaJson) as Schema;
  } catch {
    console.error("Invalid schema JSON");
    process.exit(1);
  }

  const result = validateJsonWithSchema(input, schema);
  if (result.valid) {
    console.log("Valid JSON (schema validated)");
    console.log(JSON.stringify(result.data, null, 2));
  } else {
    console.error("Validation failed:");
    console.error(`  ${result.error?.message}`);
    if (result.error?.line !== undefined) {
      console.error(`  Line: ${result.error.line}, Column: ${result.error.column}`);
    }
    process.exit(1);
  }
} else {
  const name = command ?? "World";
  console.log(greet(name));
}

